#include <linux/ioctl.h>
#include <linux/netdevice.h>
#include <linux/uaccess.h>

int ipx_ioctl(unsigned int cmd, void __user *arg) {
    int ret = 0;

    switch (cmd) {
        case SIOCSIFADDR: {
            struct sockaddr_ipx *uaddr;
            struct sock *sk;
            uaddr = memdup_user(arg, sizeof(*uaddr));
            if (IS_ERR(uaddr))
                return PTR_ERR(uaddr);
            sk = ipx_get_socket(uaddr->sipx_number);
            if (!sk) {
                ret = -EINVAL;
                break;
            }
            ret = ipx_set_address(sk, uaddr);
            sock_put(sk);
            break;
        }
        case SIOCGIFADDR: {
            struct sockaddr_ipx *uaddr;
            struct sock *sk;
            uaddr = memdup_user(arg, sizeof(*uaddr));
            if (IS_ERR(uaddr))
                return PTR_ERR(uaddr);
            sk = ipx_get_socket(uaddr->sipx_number);
            if (!sk) {
                ret = -EINVAL;
                break;
            }
            ret = ipx_get_address(sk, uaddr);
            if (!ret)
                ret = copy_to_user(arg, uaddr, sizeof(*uaddr)) ? -EFAULT : 0;
            sock_put(sk);
            break;
        }
        case SIOCAIPXITFCRT:
            ret = ipx_create_interface();
            break;
        case SIOCAIPXPRISLT: {
            int priority;
            if (copy_from_user(&priority, arg, sizeof(priority)))
                return -EFAULT;
            ret = ipx_set_priority(priority);
            break;
        }
        default:
            ret = -EINVAL;
            break;
    }

    return ret;
}

